pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address dest, uint256 amount, uint256 seed) public {
        vm.assume(actor != address(0) && dest != address(0) && dest != address(c));
        amount = bound(amount, 1 ether, 10 ether);
        seed = bound(seed, 0, 5 ether);

        // give the contract extra balance beyond what Command sends
        vm.deal(address(this), seed);
        (bool s1,) = address(c).call{value: seed}("");
        assertTrue(s1);

        uint256 before = address(c).balance;
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSelector(c.Command.selector, dest, ""));
        assertTrue(ok);

        // Rule: exactly `amount` leaves the contract via Command
        assertTrue(address(c).balance == before - amount);
    }

    receive() external payable {}
}

