pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed, address adr) public {
        // keep params in admissible domain: amount fundable, arbitrary extra pre-balance seed
        amount = bound(amount, 0, 1e30);
        seed = bound(seed, 0, 1e30);
        vm.assume(adr != address(0));

        // c's Owner is the test contract (deployer); give it an arbitrary extra balance
        vm.deal(address(c), seed);

        // caller (Owner) pays `amount` into Command with empty data
        uint256 adrBefore = address(adr).balance;
        vm.deal(address(this), amount);
        bool ok = true;
        try c.Command{value: amount}(adr, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: the call (when it does not revert) delivers exactly msg.value to adr.
        assertTrue(ok && address(adr).balance == adrBefore + amount);
    }
}

