pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Recorder rec;

    function setUp() public {
        c = new C();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount < 1 ether);
        vm.assume(data.length <= 32);
        address actor = address(0xA11CE);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Command{value: amount}(address(rec), data);
        assertTrue(rec.calledBy(address(c)) && rec.got(), "Command must call the supplied target adr, not Owner");
    }
}

contract Recorder {
    bool public got;
    address public lastCaller;

    fallback() external payable {
        got = true;
        lastCaller = msg.sender;
    }

    function calledBy(address a) external view returns (bool) {
        return lastCaller == a;
    }
}

