pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);

        // Adversarial counterparty: a callee that ACCEPTS Ether (any EOA would,
        // but we materialize the receiving counterparty explicitly).
        Accepter accepter = new Accepter();

        // Owner of c is the test contract (msg.sender at setUp).
        vm.deal(address(this), amount);
        uint256 balBefore = address(c).balance;

        vm.prank(address(this));
        c.Command{value: amount}(address(accepter), "");

        // General rule: a Command issued by the Owner forwards its msg.value to
        // the supplied recipient when that recipient accepts Ether, so the
        // contract's own balance decreases by exactly msg.value.
        assertTrue(address(c).balance == balBefore - amount);
    }
}

contract Accepter {
    receive() external payable {}
}
}

