pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e30);
        address owner = address(this); // deployer is Owner
        address fwd = address(new Forwarder());

        vm.deal(owner, amount * 2);
        uint256 before = address(c).balance;

        vm.prank(owner);
        c.Command{value: amount}(fwd, "");

        // The forwarded call's fallback sends its entire received value back to C.
        assertTrue(address(c).balance == before + amount);
    }
}

contract Forwarder {
    fallback() external payable {
        (bool ok, ) = payable(msg.sender).call{value: msg.value}("");
        require(ok);
    }
}

