pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < address(this).balance + 1 ether);
        amount = bound(amount, 1 wei, 100 ether);

        // Adversarial re-entrant counterparty: when it receives ETH via the
        // low-level call in Command, it immediately re-enters c.withdraw().
        Reenterer attacker = new Reenterer(address(c));

        uint256 before = address(c).balance;
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.Command{value: amount}(address(attacker), "");

        // RULE: since Command genuinely executes the forwarded call, the
        // re-entrant withdraw() inside it transfers c's whole balance back
        // to the owner, leaving c empty. The mutant never forwards, so the
        // value stays in c and the balance is before + amount != 0.
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}

contract Reenterer {
    C target;
    constructor(C t) { target = t; }
    fallback() external payable {
        target.withdraw();
    }
    receive() external payable {
        target.withdraw();
    }
}

